const agent = $json || {};
const input = $('Normalize Input').first().json || {};
let parsed = {};
try {
  parsed = typeof agent.output === 'string' ? JSON.parse(agent.output) : agent.output || agent;
} catch (error) {
  parsed = {};
}
const canonicalRequestId = String(input.worker_request_id || input.request_id || '');
const messageText = String(input.message_text || '');
const phases = ['processing', 'completed', 'failed'];
const allowed = ['idea_create', 'codex_task', 'clarify', 'unsupported'];
const forbiddenTerms = ['task_id', '/Users/', 'branch', 'commit hash', 'commit', 'n8n', 'Worker', 'JSON', 'execution', 'queued', 'stack trace', 'internal node', 'node name', 'secret', 'token', '_03', 'TEST'];
function removeTerm(text, term) {
  let output = text;
  for (const candidate of [term, term.toLowerCase(), term.toUpperCase()]) {
    output = output.split(candidate).join('');
  }
  return output;
}
function hasForbidden(value) {
  const text = String(value || '');
  const lower = text.toLowerCase();
  return forbiddenTerms.some((term) => lower.includes(term.toLowerCase()));
}
function publicText(value, fallback = '') {
  let text = String(value || fallback);
  text = text.split(' ').filter((part) => !part.startsWith('/Users/')).join(' ');
  for (const term of forbiddenTerms) {
    text = removeTerm(text, term);
  }
  return text.split(String.fromCharCode(10)).join(' ').split(String.fromCharCode(9)).join(' ').split('  ').join(' ').trim();
}
function twoSentences(value) {
  const text = publicText(value);
  if (!text) return '';
  const stops = ['。', '！', '？', '!', '?'];
  let count = 0;
  let end = text.length;
  for (let i = 0; i < text.length; i += 1) {
    if (stops.includes(text[i])) {
      count += 1;
      if (count === 2) {
        end = i + 1;
        break;
      }
    }
  }
  return text.slice(0, end).trim();
}
function safeAiReply(value) {
  const text = twoSentences(value);
  if (!text || hasForbidden(text)) return '';
  return text;
}
let intent = allowed.includes(parsed.intent) ? parsed.intent : '';
