  const aiGenerated = parsed.reply_source === 'ai_generated' && Boolean(replyText);
  return [{ json: {
    request_id: canonicalRequestId,
    worker_request_id: canonicalRequestId,
    intent: 'codex_task',
    phase,
    reply_text: aiGenerated ? replyText : '',
    reply_source: aiGenerated ? 'ai_generated' : 'fallback_required',
    actual_status: input.actual_status || (phase === 'completed' ? 'completed' : phase === 'failed' ? 'failed' : 'processing'),
    task_summary: input.task_summary || '',
    actual_result: input.actual_result || '',
    status: phase === 'failed' ? 'failed' : (phase === 'completed' ? 'completed' : 'accepted')
  } }];
}
const status = intent === 'unsupported' || intent === 'clarify' ? 'accepted' : (parsed.status || 'completed');
const aiReply = safeAiReply(parsed.reply_text);
const base = {
  request_id: canonicalRequestId,
  worker_request_id: canonicalRequestId,
  intent,
  reply_text: aiReply || (intent === 'codex_task' ? '我已開始處理這次任務。' : intent === 'idea_create' ? '已記下這個想法。' : '目前只支援記想法或建立測試任務。'),
  reply_source: parsed.reply_source === 'ai_generated' && aiReply ? 'ai_generated' : 'fallback_required',
  status
};
if (intent === 'idea_create') {
  return [{ json: {
    ...base,
    tool_called: 'idea_create',
    saved: true,
    saved_record: 1,
    record: 1
  } }];
}
if (intent === 'codex_task') {
  return [{ json: {
    ...base,
    tool_called: 'codex_task',
    task_id: parsed.task_id || 'pline-v3-codex-' + Date.now(),
    codex_task: 1,
    action: 'create_smoke_file',
    target_path: '/Users/phoebe/Documents/菲比 LINE 智能助理_03/codex-smoke.txt',
    content: 'Codex 已打通'
  } }];
}
return [{ json: base }];
